          console.log('[DbCollectionNode] Created new CloudStore instance');
        } catch (createError) {
          console.warn('[DbCollectionNode] Failed to create CloudStore:', createError);
        }
      }

      if (cloudStore && cloudStore.supabaseClient) {
        console.log('[DbCollectionNode] Attempting to discover Supabase tables...');

        // First try to restore from localStorage if tables were recently discovered
        let discoveredTables = [];
        if (!supabaseTablesExist) {
          try {
            const restoredTables = cloudStore._restoreTablesFromStorage();
            if (restoredTables.length > 0) {
              console.log(`[DbCollectionNode] Restored ${restoredTables.length} tables from localStorage`);
              cloudStore._updateDbCollectionsMetadata(restoredTables);
              discoveredTables = restoredTables;
            }
          } catch (restoreError) {
            console.warn('[DbCollectionNode] Failed to restore tables:', restoreError);
          }
        }

        // If no restored tables, do fresh discovery
        if (discoveredTables.length === 0) {
          discoveredTables = await cloudStore._discoverAndRegisterSupabaseTables();
        }

