  const scriptWithoutComments = script.replace(/\/\*[\s\S]*?\*\/|\/\/.*/g, ''); // Remove comments
  const inputs = scriptWithoutComments.match(/Inputs\.[A-Za-z0-9]+/g);
  if (inputs) {
    const unique = {};
    inputs.forEach((v) => {
      unique[v.substring('Inputs.'.length)] = true;
