      if (node.parameters['mode'] === 'push' || node.parameters['mode'] === undefined) {
        ports.push({
          name: 'transition',
          plug: 'input',
          type: { name: 'enum', enums: Object.keys(Transitions) },
          default: 'Push',
          displayName: 'Transition',
